      "breadcrumb": "01. Routine Dashboard / Daily / 리셋 / 생산성",
      "category": "신체관리",
      "domain": "BD",
      "topic": "RS",
      "summary": "얼굴 혈점 마사지을 Daily 기준으로 실행하기 위한 세부 매뉴얼입니다.",
      "blocks": [
        {
          "label": "목적",
          "text": "얼굴 혈점 마사지은 신체관리 영역에서 반복 가능한 자기관리 기준을 만드는 세부 루틴이다. 방법론 원칙과 라이프스타일 DB의 실행 행동을 교차해, 실제로 오늘 할 수 있는 단위로 정리했다."
        },
        {
          "label": "방법론 연결",
          "items": [
            "피부는 무언가를 더하기보다 피부를 나쁘게 만드는 접촉면, 위생, 자극을 먼저 줄이는 방식으로 관리한다. 얼굴과 목에 닿는 손, 수건, 침구, 샴푸 잔여물, 선크림 세정까지 하나의 위생 루틴으로 묶는다.",
            "면도는 도구 위생, 예열, 압력, 사후 진정을 함께 관리해야 피부 자극을 줄일 수 있다. 면도 전 예열과 도구 소독, 같은 부위 반복 면도 줄이기, 면도 후 찬물 진정과 보습을 연결한다.",
            "식단은 완전히 끊는 방식보다 대체하고 조절하는 반복 가능한 기준으로 만든다. 수분, 단백질, 장 컨디션, 당/밀가루 조절을 피부와 체형 관리의 하위 루틴으로 연결한다."
          ]
        },
        {
          "label": "실행 순서",
          "items": [
            "1. 눈가, 인중, 턱끝 등 얼굴 혈점 6곳을 누르기"
          ]
        },
        {
          "label": "반복 기준",
          "items": [
            "주기: Daily",
            "요일: 매일",
            "중요도: 추가",
            "난이도: 보통"
          ]
        },
        {
          "label": "추천 아이템",
          "items": [
            "페이스 타월 →",
            "약산성 클렌징폼 →",
            "선크림 →",
            "알코올 스왑 →",
            "면도기 →",
            "쉐이빙젤 →",
            "알코올 스프레이 →",
            "진정 크림 →",
            "단백질 →",
            "유산균 →",
            "오메가3 →",
            "물병 →"
          ]
        },
        {
          "label": "주의사항",
          "items": [
            "관리 강도를 올리기보다 반복 가능한 기준을 먼저 잡는다.",
            "자극, 비용, 시간이 커지면 루틴 단위를 낮춘다.",
            "제품 하나만 탓하지 말고 습관, 환경, 접촉면을 같이 본다."
          ]
        }
      ],
