            "스타일은 한 번 꾸미는 기술보다 헤어, 옷, 향, 생활 무드가 같은 방향으로 반복될 때 만들어진다. 셀프 스타일링, 의류 관리, 향 관리, 구매 기준을 하나의 분위기 기준으로 연결한다."
